var pending = new System.Text.StringBuilder();
string[] readChunks = { "STA", "TUS?\n" };
foreach (string chunk in readChunks) {
    pending.Append(chunk);
    bool complete = pending.ToString().EndsWith('\n');
    Console.WriteLine($"read={chunk.Length} buffered={pending.Length} complete={complete}");
}
// Expected: read=3 buffered=3 complete=False
//           read=5 buffered=8 complete=True
// For UDP, one ReceiveAsync result is one received datagram.
// Neither read completion nor a datagram boundary defines business success.
